<?php
declare(strict_types=1);
$billingStatistics = (array) ($billingStatistics ?? []); $datasets = (array) ($billingStatistics['datasets'] ?? []); $selectedMetric = clean_text((string) ($_GET['metric'] ?? $billingContext['query']['metric'] ?? 'all')); if ($selectedMetric !== 'all' && !isset($datasets[$selectedMetric])) $selectedMetric = 'all'; $visible = $selectedMetric === 'all' ? $datasets : array_intersect_key($datasets, [$selectedMetric => true]);
$format = static fn (mixed $value, string $kind): string => $kind === 'money' ? number_format((float) $value, 2, '.', ' ') . ' AZN' : number_format((float) $value, 0, '.', ' ');
?>
<div data-billing-statistics-results><div class="billing-kpis portal-section-gap"><?php foreach ((array) ($billingStatistics['kpis'] ?? []) as $kpi): ?><div class="billing-kpi" data-billing-kpi><span><?= e((string) ($kpi['label'] ?? '-')); ?></span><strong><?= e($format($kpi['value'] ?? 0, (string) ($kpi['kind'] ?? 'count'))); ?></strong></div><?php endforeach; ?></div><div class="billing-chart-grid portal-section-gap"><?php foreach ($visible as $dataset): ?><?php $rows=(array)($dataset['rows']??[]); $values=array_map(static fn(array $row):float=>(float)($row['value']??0),$rows); $max=$values===[]?1.0:max(1.0,...$values); ?><section class="billing-chart" data-billing-chart><strong><?= e((string) ($dataset['title'] ?? '-')); ?></strong><?php foreach ($rows as $row): ?><div class="billing-chart-row"><span><?= e((string) ($row['label'] ?? '-')); ?></span><span class="billing-chart-track"><b style="width:<?= e((string) min(100, ((float) ($row['value'] ?? 0) / $max) * 100)); ?>%"></b></span><strong><?= e($format($row['value'] ?? 0, (string) ($dataset['kind'] ?? 'count'))); ?></strong></div><?php endforeach; ?><?php if ($rows === []): ?><p class="billing-empty">Secilmis dovr uzre melumat yoxdur.</p><?php endif; ?></section><?php endforeach; ?></div></div>
